create or replace force view apx_mbms_approvals_v as
select a.approval_id
      ,a.doc_type
      ,d.doc_name
      ,a.doc_id
      ,a.doc_no
      ,a.approval_level
      ,a.approver_role
      ,a.amount
      ,a.requested_by
      ,a.requested_on
      ,a.status
      ,a.acted_by
      ,a.acted_on
      ,a.note
      ,apx_mbms_approval_pkg.can_act_yn(a.approval_id) can_act_yn
  from apx_mbms_approvals a
  join apx_mbms_doc_types d on d.doc_type = a.doc_type;

create or replace force view apx_mbms_user_roles_v as
select ur.user_role_id
      ,ur.username
      ,ur.role_code
      ,r.role_name
      ,ur.created_by
      ,ur.created_on
  from apx_mbms_user_roles ur
  join apx_mbms_roles r on r.role_code = ur.role_code;

