create or replace force view apx_mbms_dash_kpi_v as
select (select count(*) from apx_mbms_approvals_v where status = 'PENDING' and can_act_yn = 'Y') kpi_1
      ,(select count(*) from apx_mbms_job_orders where status in ('APPROVED', 'IN_PROGRESS')) kpi_2
      ,(select count(*) from apx_mbms_projects where status in ('APPROVED', 'IN_PROGRESS')) kpi_3
      ,(select count(*) from apx_mbms_purchase_reqs where status = 'SUBMITTED') kpi_4
      ,(select count(*) from apx_mbms_stock_on_hand_v where below_min_yn = 'Y') kpi_5
  from dual;

create or replace force view apx_mbms_dash_c1_s1_v as
select status label, count(*) value from apx_mbms_job_orders group by status;

create or replace force view apx_mbms_dash_c2_s1_v as
select wh_code label, sum(stock_value) value from apx_mbms_stock_on_hand_v group by wh_code;

create or replace force view apx_mbms_dash_c3_s1_v as
select project_no label, budget_amount value from apx_mbms_project_summary_v;

create or replace force view apx_mbms_dash_c3_s2_v as
select project_no label, actual_amount value from apx_mbms_project_summary_v;

create or replace force view apx_mbms_dash_c4_s1_v as
select job_no label, est_hpp value from apx_mbms_job_cost_v where status <> 'DRAFT';

create or replace force view apx_mbms_dash_c4_s2_v as
